492	/**
493	 * Compare two project-state snapshots and classify the difference.
494	 *
495	 * Structural changes (require full re-render):
496	 *   - The number of work packages differs between snapshots.
497	 *   - The project transitioned to COMPLETE or ARCHIVED status.
498	 *
499	 * Data-only changes (patchable in-place):
500	 *   - Status badge changed but is not a structural transition.
501	 *   - Any per-WP status or pipeline-stage changed.
502	 *   - synthesis_generated flipped.
503	 *   - health changed (including null → value transitions).
504	 *   - last_updated changed.
505	 *
506	 * NOTE — per-WP iteration order: per-WP status/pipeline changes are detected by
507	 * iterating over `next.wpStatuses` keys only. A WP present in `prev` but absent
508	 * from `next` is therefore not tracked per-field; the structural `wpCount` check
509	 * handles that case before per-WP diffing is reached. In practice, a missing WP
510	 * always triggers a structural re-render, so the per-field gap is intentional.
511	 *
512	 * @param {object} prev - Previous snapshot from _snapshotProjectState().
513	 * @param {object} next - Current  snapshot from _snapshotProjectState().
514	 * @returns {{ type: 'none'|'data'|'structural', changes: object }}
515	 */
516	function _diffProjectState(prev, next) {
517	  var changes = {};
518	  var changeType = 'none';
519	
520	  function markData(key, from, to) {
521	    changes[key] = { from: from, to: to };
522	    if (changeType === 'none') changeType = 'data';
523	  }
524	
525	  function markStructural(key, from, to) {
526	    changes[key] = { from: from, to: to };
527	    changeType = 'structural';
528	  }
529	
530	  // ── WP count ────────────────────────────────────────────────────────
531	  var prevIds = Object.keys(prev.wpStatuses || {});
532	  var nextIds = Object.keys(next.wpStatuses || {});
533	  if (prevIds.length !== nextIds.length) {
534	    markStructural('wpCount', prevIds.length, nextIds.length);
535	  }
536	
537	  // ── Project status ──────────────────────────────────────────────────
538	  if (prev.status !== next.status) {
539	    var isStructuralStatus = next.status === 'COMPLETE' || next.status === 'ARCHIVED';
540	    if (isStructuralStatus) {
541	      markStructural('status', prev.status, next.status);
542	    } else {
543	      markData('status', prev.status, next.status);
544	    }
545	  }
546	
547	  // ── Per-WP statuses and pipeline stages ─────────────────────────────
